btopic", "title": "Board-ready communication", "children": [{"id": "f5b9e6ba-2238-4218-93e3-e14800cd2390", "type": "concept", "title": "Memo"}, {"id": "1e8b9d88-68ba-4e22-8cbe-0ccdb4b4c76d", "type": "concept", "title": "Presentation"}, {"id": "bfd6801f-d97f-4884-9758-54ba299ae208", "type": "concept", "title": "Recommendation, tradeoffs, and implementation plan"}], "description": "The final product should support executive decision-making."}]}], "dbBacked": true}$blejson$::jsonb,
