habits"}, {"id": "7e6284d0-3fe3-4182-ab52-10dd4801a7fa", "type": "concept", "title": "Risk tolerance and escalation"}], "description": "Managers do not need to be lawyers, but they need to spot legal risk early."}]}, {"id": "6dd83431-219e-4fa7-adf3-77256e987abf", "type": "topic", "title": "Courts, Litigation, Alternative Dispute Resolution, and Risk Strategy", "description": "This topic explains how disputes move through courts, arbitration, mediation, and settlement decisions.", "children": [{"id": "6dbb0de7-c06b-4b1b-9713-f36dad98f2e3", "type": "subtopic", "title": "Court systems", "children": [{"id": "8a6559c1-fd12-4a2e-b829-a9cbb8b44827", "type": "concept", "title": "Jurisdiction and venue"}, {"id": "624217d4-00ce-44c2-91e7-146ef940ec13", "type": "concept", "title": "State and federal courts"}, {"id": "cdb9b638-736f-4b32-9e0c-7606241e2a32", "type": "concept", "title": "Appeals"}], "description": "Students learn where disputes are heard and why forum matters."}, {"id": "34f5a07d-b883-4c44-8071-2d81ae1066d0", "type": "subtopic", "title": "Civil litigation", "children": [{"id": "7b548a46-09a0-4da8-b765-7384e89aff1f", "type": "concept", "title": "Pleadings and motions"}, {"id": "2836dc39-a5d0-4055-b7d7-9d59f73110f7", "type": "concept", "title": "Discovery"}, {"id": "39a961d8-be56-4eb7-9d9b-162bd2b4ddfc", "type": "concept", "title": "Trial and judgment"}], "description": "Litigation is a process with strategic costs, evidence duties, and reputational stakes."}, {"id": "2c7d5c27-ba43-4e3f-9ec6-12214f215fdc", "type": "subtopic", "title": "ADR and settlement", "children": [{"id": "c634bc60-9993-4955-9990-e03d47b6c121", "type": "concept", "title": "Negotiation"}, {"id": "408b9b02-aee1-43b3-ba9d-e4aa7a49aac9", "type": "concept", "title": "Mediation"}, {"id": "b68198c6-dc83-4e7f-895d-bf3d33dd830a", "type": "concept", "title": "Arbitration clauses"}], "description": "Many business disputes are managed outside trial."}]}, {"id": "9679c5b3-6922-43af-a57e-aad880f9bd4f", "type"